{
  "status": "SUPPORTED",
  "task_summary": "Identify and retrieve fastening hardware and tools from storage, fasten a component to a workpiece on the workbench, and leave the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "The hardware (bolt, screw, nut, etc.) needed to secure the workpiece.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["bolt", "screw", "nut", "clip", "fastener"],
        "required_properties": ["compatible with workpiece"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastening force.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["wrench", "screwdriver", "drill", "hammer"],
        "required_properties": ["capable of driving fastening_component"]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The object being fastened or the surface receiving the fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["workbench", "fixture", "clamp", "object"],
        "required_properties": ["located at marked workbench location"]
      },
      {
        "id": "storage_region",
        "entity_kind": "REGION",
        "function": "Closed containers where fastening components and tools may be stored.",
        "required_count": 3,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["drawer", "cabinet", "compartment"],
        "required_properties": ["closed", "accessible"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The destination surface where the tool is left after the task.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["table", "bench"],
        "required_properties": ["flat", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "connects_to",
        "relation": "fastening_component connects to workpiece",
        "participant_roles": ["fastening_component", "workpiece"]
      ,
      "required": true
      },
      {
        "id": "operates_on",
        "relation": "fastening_tool operates on fastening_component",
        "participant_roles": ["fastening_tool", "fastening_component"]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_for_components",
        "operation": "inspect storage_region to locate fastening_component and fastening_tool",
        "participant_roles": ["storage_region", "fastening_component", "fastening_tool"]
      ,
      "operation_count": 3
      },
      {
        "id": "perform_fastening",
        "operation": "fasten fastening_component to workpiece using fastening_tool",
        "participant_roles": ["fastening_component", "workpiece", "fastening_tool"]
      ,
      "operation_count": 1
      },
      {
        "id": "leave_tool",
        "operation": "place fastening_tool on workbench_surface",
        "participant_roles": ["fastening_tool", "workbench_surface"]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_component": [],
      "fastening_tool": [],
      "workpiece": [
        {
          "label": "yellow_object_on_tray",
          "visual_description": "Yellow rectangular object on a black tray on the workbench surface."
        }
      ],
      "storage_region": [
        {
          "label": "left_drawer",
          "visual_description": "Blue drawer under the left side of the workbench."
        },
        {
          "label": "right_drawer",
          "visual_description": "Blue drawer under the right side of the workbench."
        },
        {
          "label": "blue_cabinet",
          "visual_description": "Tall blue cabinet behind the workbench."
        }
      ],
      "workbench_surface": [
        {
          "label": "wooden_table_top",
          "visual_description": "Wooden surface of the workbench."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue_cabinet",
        "visual_description": "Tall blue cabinet with a handle, closed.",
        "reason": "Likely contains tools or hardware components."
      },
      {
        "id": "left_drawer",
        "label": "left_drawer",
        "visual_description": "Blue drawer with a handle, closed.",
        "reason": "Likely contains small hardware or tools."
      },
      {
        "id": "right_drawer",
        "label": "right_drawer",
        "visual_description": "Blue drawer with a handle, closed.",
        "reason": "Likely contains small hardware or tools."
      }
    ],
    "inspection_order": ["blue_cabinet", "left_drawer", "right_drawer"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
